import{_ as o,o as a,c as i,a2 as t}from"./chunks/framework.DBYUAoKZ.js";const m=JSON.parse('{"title":"Admin internals","description":"","frontmatter":{},"headers":[],"relativePath":"docs/admin-internals.md","filePath":"docs/admin-internals.md"}'),d={name:"docs/admin-internals.md"};function n(s,e,c,r,l,h){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="admin-internals" tabindex="-1">Admin internals <a class="header-anchor" href="#admin-internals" aria-label="Permalink to &quot;Admin internals&quot;">​</a></h1><p>How the server enforces the rules of <a href="./admin">the admin area</a>. Read this when you change admin code. Every admin route is under <code>/api/v1/admin/</code> and described in the OpenAPI document, which is the full reference.</p><h2 id="access" tabindex="-1">Access <a class="header-anchor" href="#access" aria-label="Permalink to &quot;Access&quot;">​</a></h2><ul><li>Admin is a <code>role</code> on the account (<code>member</code> or <code>admin</code>), not a scope (<a href="./adr/0020-every-credential-resolves-to-one-caller">ADR 0020</a>).</li><li>The server accepts the access cookie only from the website client (<a href="./the-api#browser-session-admin-website">the API</a>). The API answers the website&#39;s origin with <code>Access-Control-Allow-Credentials</code>, so the page calls it with <code>credentials: &#39;include&#39;</code>.</li><li>An anonymous caller gets 401. A member, an admin on the phone app, a personal access token or a third-party app gets 403.</li><li>A write whose <code>Origin</code> is not the website&#39;s gets 403. This is the CSRF defence.</li><li>A member who signs in on the website is signed out with the same answer as any refusal, so the role isn&#39;t disclosed.</li><li><code>ADMIN_EMAIL</code> is read at start-up. The promotion is an <code>AdminAction</code>.</li></ul><h2 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h2><ul><li><code>AdminAccounts.list</code> reads every account row and cuts the page in memory. Enough for a back office; move it into SQL if accounts reach the hundreds of thousands.</li><li>The list takes <code>q</code>, <code>role</code>, <code>confirmed</code>, <code>signIn</code>, <code>sort</code>, <code>order</code>, <code>page</code> and <code>size</code>. A word that isn&#39;t allowed is <code>400 bad-query</code>.</li><li>Disabling revokes every access and refresh token of the account.</li><li>Deleting runs the same code as the user&#39;s own deletion and needs <code>{&quot;confirmEmail&quot;: …}</code>.</li><li>An admin acting on their own account gets <code>409 own-account</code>.</li></ul><h2 id="settings-and-mail" tabindex="-1">Settings and mail <a class="header-anchor" href="#settings-and-mail" aria-label="Permalink to &quot;Settings and mail&quot;">​</a></h2><ul><li>Settings are one row each in the <code>settings</code> table (<code>ServerSettings</code>). The SMTP host, port, user and password stay in the environment.</li><li>Every email goes through <code>SettingsMailer</code>, which reads <code>mail-from</code> when it sends, so a saved address applies with no restart. <code>MAIL_FROM</code> is the default.</li><li>An address that doesn&#39;t parse is <code>400 invalid-address</code>.</li><li><code>SettingsMailer.last</code> keeps the last send (when, kind, masked recipient, error) in memory.</li><li>Mail is configured when <code>SMTP_HOST</code> is set. Without it, sending fails with <code>No mail server is set: SMTP_HOST is unset</code>, and the error isn&#39;t printed to the log.</li><li>Routes: <code>GET /api/v1/admin/settings</code>, <code>POST …/settings/mail-from</code>, <code>POST …/settings/test-email</code>.</li></ul><h2 id="status-and-pending-registrations" tabindex="-1">Status and pending registrations <a class="header-anchor" href="#status-and-pending-registrations" aria-label="Permalink to &quot;Status and pending registrations&quot;">​</a></h2><ul><li>Routes: <code>GET /api/v1/admin/status</code>, <code>GET …/pending-registrations</code> and <code>POST …/pending-registrations/{id}/confirm</code> (<code>204</code>, <code>404 unknown-account</code>, <code>409 already-confirmed</code>).</li><li>Confirming by hand has the same effect as the link: the account can sign in, its pending links stop working and a phone waiting for the link hears it.</li><li>The public <code>GET /api/v1/status</code> never says how the server is configured, and a test holds it to that.</li></ul><h2 id="catalog" tabindex="-1">Catalog <a class="header-anchor" href="#catalog" aria-label="Permalink to &quot;Catalog&quot;">​</a></h2><ul><li>Storage is <code>catalog_exercise_revision</code>. Publishing writes rows only for the exercises it names (<a href="./adr/0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version">ADR 0030</a>).</li><li>An exercise is the catalog&#39;s JSON, every text a map from language to string.</li><li>Refusals: <code>409 slug-published</code>, <code>409 slug-taken</code>, <code>409 missing-translations</code> (listing exercises and languages), <code>409 no-changes</code>, <code>400 invalid-exercise</code> with a <code>reason</code>, <code>404 unknown-exercise</code>, <code>400 bad-query</code>.</li><li>The list filters by <code>q</code>, <code>pattern</code>, <code>muscles</code>, <code>positions</code>, <code>equipment</code>, <code>translation</code>, <code>content</code> and <code>lifecycle</code>, and sorts by <code>name</code>, <code>pattern</code>, <code>languages</code>, <code>change</code> and <code>status</code>. Content, translation and lifecycle are separate dimensions.</li><li><code>GET …/catalog/changes</code> returns what publishing would do, and each edited field as <code>{field, before, after}</code>.</li><li><code>POST …/catalog/publish</code> takes an optional <code>{&quot;slugs&quot;: […]}</code>.</li></ul><h2 id="audit-log" tabindex="-1">Audit log <a class="header-anchor" href="#audit-log" aria-label="Permalink to &quot;Audit log&quot;">​</a></h2><ul><li>An admin action is an <code>AdminAction</code> event sent through http4k&#39;s <code>Events</code>. One sink stores it in <code>admin_audit</code> and another prints it to the server log. Tests check it with <code>RecordingEvents</code>.</li><li>Actions: <code>admin.account.disable</code>, <code>admin.account.enable</code>, <code>admin.account.delete</code>, <code>admin.account.confirm</code>, <code>admin.settings.mail-from</code>, <code>admin.catalog.create</code>, <code>admin.catalog.edit</code>, <code>admin.catalog.retire</code>, <code>admin.catalog.offer</code> and <code>admin.catalog.publish</code>.</li><li><code>GET /api/v1/admin/audit</code> returns the last 100 rows.</li><li><code>EmailAddress</code> is a values4k type that prints masked, so an address that reaches a log by accident stays hidden. Read the real one with <code>.value</code> only where needed. An event never carries a password or an unmasked address.</li></ul>',14)])])}const g=o(d,[["render",n]]);export{m as __pageData,g as default};
